import unittest
from logic import solve
class ContractRegression(unittest.TestCase):
 def test_contract_boundaries(self):
  for value,expected in [({'text': 'a+b'}, 'a+b'), ({'text': '%C3%A9'}, 'é'), ({'text': '%GG'}, None), ({'text': '%FF'}, None)]:
   with self.subTest(value=value):self.assertEqual(solve(value),expected)
